def fig(head, hip, arms, legs, c=TL):
    """Posed figure: head point, hip point, arm and leg paths (lists of points) drawn from shoulder and hip."""
    (hx, hy), (px, py) = head, hip
    sh = (round(hx + (px - hx) * 0.3), round(hy + 12 + (py - hy - 12) * 0.2))
    out = [line(hx, hy + 8, px, py, 10, c), O(hx, hy, 9, 9, SK)]
    out += [s for a in arms for s in polyline([sh] + a, 5, c)]
    out += [s for g in legs for s in polyline([hip] + g, 7, IN)]
    return out


def hand(cx, cy, c=SK):
    return [O(cx, cy, 14, 12, c), R(cx - 10, cy + 6, 20, 16, c)]


def ball(cx, cy, r, c):
    return [O(cx, cy, r, r, c, 14), arc(cx, cy, r - 3, r, 200, 340, CR, 6)]


